      if (T.step === 'gate') return wrap(`<h2>Before you take a photo</h2><p class="small muted mt8">This is the only part of FitFirst where a photo leaves your phone. Each choice is separate.</p><form id="gate" class="col mt16"><label class="check card"><input type="checkbox" name="age" data-change="p-gate" ${T.c.age ? 'checked' : ''}><span><b>I am 18 or older</b><br><span class="small muted">Try-on is for adults only.</span></span></label><label class="check card"><input type="checkbox" name="proc" data-change="p-gate" ${T.c.proc ? 'checked' : ''}><span><b>Use my photo to make a preview</b><br><span class="small muted">One full-body photo, used only for this preview and deleted within ${FF.db.settings.retention.tryonHours} hours.</span></span></label><label class="check card"><input type="checkbox" name="xfer" data-change="p-gate" ${T.c.xfer ? 'checked' : ''}><span><b>Send it to the AI service that makes the image</b><br><span class="small muted">Sent securely to our image provider (a paid tier that does not train on your photo). Not shared with anyone else.</span></span></label></form><p class="tiny muted mt12">${left} of ${v.tryLimit || 3} try-ons left for this visit · every result is labelled “AI-generated preview”.</p>`, `<button class="btn btn-p btn-l grow" data-act="p-try-next" ${T.c.age && T.c.proc && T.c.xfer ? '' : 'disabled'}>Continue</button>`);
      if (T.step === 'photo') return wrap(`<h2>Take a full-body photo</h2><p class="small muted mt8">Stand straight, arms slightly away from your body, plain background if you can.</p><div class="gimg mt16" style="aspect-ratio:2/3;max-width:230px;margin-inline:auto">${T.photo ? (T.photo === 'sample' ? FF.figure(p, skin, false) : `<img src="${T.photo}" alt="Your photo" style="width:100%;height:100%;object-fit:cover">`) : `<div style="display:grid;place-items:center;height:100%;color:var(--muted)">${FF.icon('camera')}</div>`}</div>${T.photo ? `<p class="note n-ok mt12">${FF.icon('check', 'hide')}✓ Pose check passed — one person, full body in frame.</p>` : ''}<div class="col mt16"><label class="btn btn-block">${FF.icon('camera')} ${T.photo ? 'Retake photo' : 'Take or choose a photo'}<input type="file" accept="image/*" capture="user" data-change="p-photo" style="position:absolute;opacity:0;width:1px;height:1px"></label><button class="btn btn-g" data-act="p-sample">Use the sample figure (prototype)</button></div>
        ${FF.groupOf(p).size === 'FREE' && p.shape === 'saree' ? `<h4 class="mt16">Drape style</h4><div class="row wrap mt8">${['Nivi', 'Gujarati seedha pallu', 'Bengali', 'Nauvari'].map((d) => `<button class="chip" data-act="p-drape" data-v="${d}" aria-pressed="${T.drape === d}">${d}</button>`).join('')}</div>` : ''}`, `<button class="btn btn-p btn-l grow" data-act="p-try-next" ${T.photo ? '' : 'disabled'}>Make my preview</button>`);
