  FF.act('p-heart', (d) => { const v = visit(), i = v.shortlist.indexOf(d.pid); i < 0 ? v.shortlist.push(d.pid) : v.shortlist.splice(i, 1); const pk = v.picks.find((x) => x.pid === d.pid); if (pk && pk.state !== 'bought') pk.state = i < 0 ? 'shortlisted' : 'shown'; ev(v, 'shortlist', (i < 0 ? 'Added ' : 'Removed ') + FF.prod(d.pid).name + ' (phone)'); FF.save(); render(); FF.toast(i < 0 ? 'Added — staff can see your list' : 'Removed', i < 0 ? 'ok' : ''); });
