  FF.act('p-otp', (f) => { const v = visit(); v.remember = '••••••' + f.phone.slice(-4); FF.db.consents.unshift({ at: Date.now(), code: v.code, purpose: 'Save profile', granted: true, notice: 'N-3', lang: FF.lang, method: 'Phone OTP' }); FF.save(); FF.closeOverlay(); render(); FF.toast('Profile saved', 'ok'); });
  FF.act('p-privacy', () => { const v = visit(); FF.modal({ title: 'Privacy and my data', body: `<dl class="kv small"><dt>Kept about this visit</dt><dd>Your answers, the pieces shown and what you tried</dd><dt>Not kept</dt><dd>Camera frames. Try-on photos are deleted within ${FF.db.settings.retention.tryonHours} hours</dd><dt>Deleted automatically</dt><dd>${FF.fmtDate(v.at + FF.db.settings.retention.visitDays * FF.DAY)}</dd><dt>Try-ons used</dt><dd>${v.tryons || 0}</dd><dt>Questions</dt><dd>${esc(st().phone)}</dd></dl><hr><h3>Delete my data now</h3><p class="small muted mt4">Removes your answers, picks and any try-on images for visit ${v.code}. If you bought something, the bill itself is kept because GST law requires it.</p>`, footer: `<button class="btn" data-act="close">Close</button><button class="btn btn-d" data-act="p-erase">Delete my data</button>` }); });
